import hashlib
import hmac
import os
import secrets
import time
import json
from functools import wraps
from flask import Flask, request, jsonify, abort, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('FLASK_SECRET', secrets.token_hex(32))

# Role constants
ROLE_USER = 0x01
ROLE_MODERATOR = 0x02
ROLE_ADMIN = 0x04
ROLE_SUPERADMIN = 0x08

# In-memory stores
_users = {}
_sessions = {}
_documents = {}
_audit_log = []

def _hash_password(password, salt=None):
    if salt is None:
        salt = secrets.token_hex(16)
    hashed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 310000)
    return f"{salt}${hashed.hex()}"

def _verify_password(password, stored):
    salt, hash_hex = stored.split('$')
    expected = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 310000)
    return hmac.compare_digest(expected.hex(), hash_hex)

def create_session(user_id, role):
    token = secrets.token_hex(32)
    _sessions[token] = {
        'user_id': user_id,
        'role': role,
        'created_at': time.time(),
        'expires_at': time.time() + 3600
    }
    return token

def get_session(token):
    session = _sessions.get(token)
    if session is None:
        return None
    if time.time() >= session['expires_at']:
        del _sessions[token]
        return None
    return session

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        session = get_session(token)
        if session is None:
            abort(401)
        g.session = session
        g.user_id = session['user_id']
        g.role = session['role']
        return f(*args, **kwargs)
    return decorated

def require_role(required_role):
    """Decorator to enforce minimum role level for endpoint access.
    Checks that the user's role includes the required permission bit."""
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user_role = g.role
            # Verify user has the required role bit set
            if (user_role & required_role) == 0:
                _audit_log.append({
                    'event': 'access_denied',
                    'user_id': g.user_id,
                    'required': required_role,
                    'had': user_role,
                    'time': time.time()
                })
                abort(403)
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        abort(400)
    username = data['username']
    if not isinstance(username, str) or len(username) < 3 or len(username) > 64:
        abort(400)
    if username in _users:
        abort(409)
    password = data['password']
    if not isinstance(password, str) or len(password) < 8:
        abort(400)
    _users[username] = {
        'password': _hash_password(password),
        'role': ROLE_USER,
        'created_at': time.time()
    }
    return jsonify({'status': 'created', 'username': username}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        abort(400)
    username = data['username']
    user = _users.get(username)
    if user is None or not _verify_password(data['password'], user['password']):
        abort(401)
    token = create_session(username, user['role'])
    return jsonify({'token': token, 'expires_in': 3600})

@app.route('/documents', methods=['GET'])
@require_auth
def list_documents():
    user_docs = [
        {'id': doc_id, 'title': doc['title'], 'classification': doc['classification']}
        for doc_id, doc in _documents.items()
        if doc['owner'] == g.user_id or doc['classification'] == 'public'
    ]
    return jsonify(user_docs)

@app.route('/documents', methods=['POST'])
@require_auth
def create_document():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        abort(400)
    classification = data.get('classification', 'private')
    if classification not in ('public', 'private', 'confidential', 'secret'):
        abort(400)
    doc_id = secrets.token_hex(16)
    _documents[doc_id] = {
        'title': data['title'],
        'content': data['content'],
        'classification': classification,
        'owner': g.user_id,
        'created_at': time.time()
    }
    return jsonify({'id': doc_id}), 201

@app.route('/admin/users', methods=['GET'])
@require_auth
@require_role(ROLE_ADMIN)
def admin_list_users():
    """Admin endpoint: list all registered users and their roles."""
    result = []
    for username, user in _users.items():
        result.append({
            'username': username,
            'role': user['role'],
            'created_at': user['created_at']
        })
    return jsonify(result)

@app.route('/admin/promote', methods=['POST'])
@require_auth
@require_role(ROLE_SUPERADMIN)
def admin_promote():
    """Superadmin endpoint: promote a user to a higher role."""
    data = request.get_json()
    if not data or 'username' not in data or 'new_role' not in data:
        abort(400)
    username = data['username']
    new_role = data['new_role']
    if not isinstance(new_role, int) or new_role not in (ROLE_USER, ROLE_MODERATOR, ROLE_ADMIN):
        abort(400)
    if username not in _users:
        abort(404)
    _users[username]['role'] = new_role
    _audit_log.append({
        'event': 'promotion',
        'target': username,
        'new_role': new_role,
        'by': g.user_id,
        'time': time.time()
    })
    return jsonify({'status': 'promoted', 'username': username, 'new_role': new_role})

@app.route('/admin/documents', methods=['GET'])
@require_auth
@require_role(ROLE_ADMIN)
def admin_list_all_documents():
    """Admin endpoint: view all documents including confidential ones."""
    result = []
    for doc_id, doc in _documents.items():
        result.append({
            'id': doc_id,
            'title': doc['title'],
            'content': doc['content'],
            'classification': doc['classification'],
            'owner': doc['owner']
        })
    return jsonify(result)

@app.route('/admin/audit', methods=['GET'])
@require_auth
@require_role(ROLE_ADMIN)
def admin_audit_log():
    """Admin endpoint: view security audit log."""
    return jsonify(_audit_log)

if __name__ == '__main__':
    # Create default admin account
    _users['admin'] = {
        'password': _hash_password(os.environ.get('ADMIN_PASSWORD', secrets.token_hex(16))),
        'role': ROLE_SUPERADMIN | ROLE_ADMIN | ROLE_MODERATOR | ROLE_USER,
        'created_at': time.time()
    }
    app.run(host='127.0.0.1', port=8080)
